// createTestComponent creates a basic test component with unconnected NATS client
func createTestComponent(t *testing.T) *Component {
	t.Helper()

	// Create unconnected NATS client (won't actually connect)
	natsClient, err := natsclient.NewClient("nats://localhost:4222")
	require.NoError(t, err)

	config := DefaultConfig()
	deps := component.Dependencies{
		NATSClient: natsClient,
	}

	configJSON, err := json.Marshal(config)
	require.NoError(t, err)

	comp, err := CreateGraphGateway(configJSON, deps)
	require.NoError(t, err)

	return comp.(*Component)
}

func validTestPortConfig() *component.PortConfig {
	return &component.PortConfig{
		Outputs: canonicalQueryOutputs("graph.query.*", "graph.index.query.*", "agentic.query.*"),
	}
}
